(function(){'use strict';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),product=new URLSearchParams(location.search).get('product');let content,step=0,answers={},reminders={},dirty=false,pending,access=false,checking=false;
const validProduct=['aggrieved','respondent'].includes(product);$('guide-checkout').href='/shop.html?product='+(validProduct?product:'aggrieved');
async function api(path){const r=await fetch('/api/shop/'+path,{credentials:'same-origin',signal:AbortSignal.timeout(20000)});let d;try{d=await r.json()}catch{throw Error('Access could not be verified. Keep this tab open and save local progress.');}if(!r.ok)throw Error(d.error||'Product access is unavailable.');return d;}
function message(s,error=false){$('individual-status').textContent=s;$('individual-status').className=error?'error':'small';}
function state(){return {format:'navigator-individual-guide',version:1,product,step,answers:{...answers},reminders:JSON.parse(JSON.stringify(reminders))};}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);}
$('individual-save').onclick=()=>{if(!content)return;download('Navigator-'+product+'-Guide-Recovery.json',JSON.stringify(state(),null,2),'application/json');dirty=true;message('Recovery download requested. Check that the file has finished saving before closing. Restore it in a fresh tab to verify it; Navigator cannot confirm a browser download was saved.');};
function doc(id){const d=content?.drafts[id];if(!d)return;window.NavigatorDocx.download('Navigator-'+product+'-'+id+'.docx',window.NavigatorDocx.buildDocx(d.title,[{type:'title',text:d.title},{type:'p',text:'Editable personal preparation draft. Complete and check it offline. Not submitted, issued or legally approved.'},...d.body.split('\n').map(text=>({type:'p',text})),{type:'p',text:'Navigator self-service guide · Edition '+content.edition+' · Keep confidential records securely.'}],{workflow:true}));message('Editable draft download requested. Review and complete it offline; no filing or service occurred.');}
function render(){if(!content)return;$('guide-title').textContent=content.title;const count=Object.keys(answers).length;$('individual-progress').style.width=(count/content.steps.length*100)+'%';$('individual-steps').innerHTML=content.steps.map((s,i)=>'<button type="button" data-stage="'+i+'" '+(i===step?'aria-current="step"':'')+' '+(i>count?'disabled':'')+' aria-label="'+esc(s.title)+'">'+(i+1)+'</button>').join('');$('individual-plan').innerHTML=content.steps.filter(s=>answers[s.id]).map(s=>{const o=s.options.find(o=>o.id===answers[s.id]),r=reminders[s.id];return '<li><strong>'+esc(s.title)+'</strong><br>'+esc(o.label)+'<br>'+esc(o.pending?'Follow-up remains to be reviewed':'Preparation selection recorded')+'<details><summary>Review the next action</summary><p>'+esc(o.body)+'</p></details>'+(r?' · Personal review '+esc(r.date)+(r.done?' · Marked reviewed':''):'')+'</li>';}).join('')||'<li>Answer the current question to build your preparation plan.</li>';$('individual-draft-library').innerHTML=Object.entries(content.drafts).map(([id,d])=>'<button type="button" data-draft="'+esc(id)+'">'+esc(d.title)+'</button>').join('');
 if(step===content.steps.length){const open=content.steps.filter(s=>s.options.find(o=>o.id===answers[s.id])?.pending&&!reminders[s.id]?.done);$('individual-step').innerHTML='<p class="kicker">Preparation review</p><h2 id="individual-question">Your preparation plan is ready to review</h2><p>'+count+' stages reviewed. '+open.length+' follow-up item'+(open.length===1?'':'s')+' remain for your attention.</p><p>This does not close a complaint, establish compliance, determine a finding or replace actual Committee directions. Review open requests and any legal remedy promptly.</p><div class="actions"><button type="button" data-review-first>Review the first stage</button><a class="button" href="/shop.html?product='+product+'">Access and renewal options</a></div><p>Save your recovery file before closing this tab. Retain submitted documents and receipts separately in secure records.</p>';return;}
 const s=content.steps[step],o=s.options.find(o=>o.id===answers[s.id]);$('individual-step').innerHTML='<p class="kicker">Stage '+(step+1)+' of '+content.steps.length+' · '+esc(s.title)+'</p><h2 id="individual-question">'+esc(s.question)+'</h2><div class="choices">'+s.options.map(x=>'<button type="button" data-option="'+esc(x.id)+'" aria-pressed="'+(o?.id===x.id)+'">'+esc(x.label)+'</button>').join('')+'</div>'+(o?'<section class="guide-output" aria-label="Relevant guidance"><p>'+esc(o.body)+'</p></section>'+(o.docs.length?'<h3>Drafts relevant here</h3><div class="draft-list">'+o.docs.map(id=>'<button type="button" data-draft="'+esc(id)+'">Download '+esc(content.drafts[id].title)+'</button>').join('')+'</div>':'')+'<details><summary>Personal review reminder</summary><p class="small">Enter a date you choose or verify against an actual direction. This is not a statutory deadline calculator.</p><label for="personal-review-date">Personal review date</label><input id="personal-review-date" type="date" value="'+esc(reminders[s.id]?.date||'')+'"><label class="check"><input id="personal-review-done" type="checkbox" '+(reminders[s.id]?.done?'checked':'')+'><span>I have reviewed this personal action against my own records.</span></label><button type="button" data-save-reminder>Record reminder</button></details><div class="actions"><button class="primary" type="button" data-next>Continue my preparation</button></div>':'<p class="small">Choose the actual situation to see relevant guidance and drafts.</p>');}
$('individual-workspace').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(!access&&!['individual-save','individual-restore-cancel'].includes(b.id))return;if(b.dataset.draft){doc(b.dataset.draft);return;}if(b.dataset.stage!==undefined){step=Number(b.dataset.stage);render();return;}if(b.dataset.option){const s=content.steps[step];if(!s.options.some(o=>o.id===b.dataset.option))return;if(answers[s.id]!==b.dataset.option){for(const later of content.steps.slice(step+1)){delete answers[later.id];delete reminders[later.id];}delete reminders[s.id];}answers[s.id]=b.dataset.option;dirty=true;render();return;}if(b.hasAttribute('data-next')){step++;dirty=true;render();$('individual-question').tabIndex=-1;$('individual-question').focus();return;}if(b.hasAttribute('data-review-first')){step=0;render();return;}if(b.hasAttribute('data-save-reminder')){const date=$('personal-review-date').value,done=$('personal-review-done').checked;if(date&&!/^\d{4}-\d{2}-\d{2}$/.test(date)){message('Choose a valid personal review date.',true);return;}if(date)reminders[content.steps[step].id]={date,done};else delete reminders[content.steps[step].id];dirty=true;render();message('Personal reminder recorded in this tab. Save local progress to keep it.');}});
$('individual-restore-open').onclick=()=>{if(!access)return;$('individual-restore').hidden=false;$('individual-file').focus();};$('individual-restore-cancel').onclick=()=>{pending=null;$('individual-restore').hidden=true;$('individual-restore-confirm').hidden=true;};
function validate(d){const plain=x=>x&&typeof x==='object'&&!Array.isArray(x),keys=(x,list)=>Object.keys(x).every(k=>list.includes(k));if(!plain(d)||!keys(d,['format','version','product','step','answers','reminders'])||d.format!=='navigator-individual-guide'||d.version!==1||d.product!==product||!Number.isInteger(d.step)||d.step<0||d.step>content.steps.length||!plain(d.answers)||!plain(d.reminders))throw Error('This file does not match this guide. Current progress is unchanged.');let gap=false,count=0;for(const s of content.steps){if(d.answers[s.id]){if(gap||!s.options.some(o=>o.id===d.answers[s.id]))throw Error('Invalid or out-of-order preparation choices.');count++;}else gap=true;}if(Object.keys(d.answers).length!==count||d.step>count)throw Error('Invalid preparation progress.');for(const [id,r]of Object.entries(d.reminders)){if(!d.answers[id]||!plain(r)||!keys(r,['date','done'])||typeof r.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||new Date(r.date+'T00:00:00Z').toISOString().slice(0,10)!==r.date||typeof r.done!=='boolean')throw Error('Invalid personal reminder.');}return d;}
$('individual-file').onchange=async e=>{pending=null;$('individual-restore-confirm').hidden=true;try{const f=e.target.files[0];if(!f)return;if(f.size>200000)throw Error('Recovery file is too large.');pending=validate(JSON.parse(await f.text()));$('individual-restore-preview').textContent=Object.keys(pending.answers).length+' stages and '+Object.keys(pending.reminders).length+' personal reminders. Replacing will overwrite this tab’s preparation choices. Save current progress first if needed.';$('individual-restore-confirm').hidden=false;}catch(e){message(e.message||'File could not be checked. Current progress is unchanged.',true);}};
$('individual-restore-confirm').onclick=()=>{if(!pending||!access)return;const d=validate(pending);answers={...d.answers};reminders=JSON.parse(JSON.stringify(d.reminders));step=d.step;pending=null;dirty=true;$('individual-restore').hidden=true;render();message('Restored locally. Verify the imported choices against your records, then save a fresh recovery file.');};
$('individual-print').onclick=()=>window.print();window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function check(){if(checking)return;checking=true;try{if(!validProduct)throw Error('Choose the aggrieved-woman or respondent guide from Digital products.');const s=await api('session?product='+product);if(!s.hasTestAccess)throw Error(s.signedIn?'Complete test checkout for this guide to continue.':'Sign in and complete test checkout for this guide.');if(!content){content=await api('content?product='+product);render();}access=true;$('guide-access-hold').hidden=true;$('individual-workspace').hidden=false;$('individual-workspace').inert=false;$('individual-restore-open').disabled=false;}catch(e){access=false;$('guide-access-hold').hidden=false;$('guide-access-title').textContent='Guide access needs verification';$('guide-access-message').textContent=e.message;if(content){$('individual-workspace').hidden=false;$('individual-step').inert=true;$('individual-steps').inert=true;$('individual-restore-open').disabled=true;message('Your work remains in this tab. Save local progress before leaving. Recheck access after test checkout or sign-in.',true);}}finally{if(access){$('individual-step').inert=false;$('individual-steps').inert=false;}checking=false;}}
$('guide-recheck').onclick=check;check();setInterval(check,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check();});
})();
